//! 🪨️ Full masonry persistence, independent domain interpretation and actual declaration-owned I/O laws.
use crate::standards::v1::subsets::any::io::sqlite::snapshot::En1996Snapshot;
#[test]
fn sqlite_snapshot_en1996_owned_native_decoder_controls_both_physical_payloads(){
 use store::io::IoPayload;
 let snapshot=fixture();let limits=SqliteDatabaseLimits::default();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot)),SnapshotEncoding::Text=>IoPayload::Text(store::ArtifactDsl::print_dsl(&snapshot))};
  let restored=En1996Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored,snapshot);
  assert!(En1996Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());
  assert!(En1996Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:1,..limits})).is_err());
  assert!(En1996Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1,..limits})).is_err());
 }
}
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{export_sqlite_database,import_sqlite_database,SnapshotEncoding,SqliteDatabase,SqliteDatabaseLimits,SqliteSnapshotControl,SqliteSnapshotPhase,SqliteValue}};

fn fixture()->En1996Snapshot{semio_framework_pack_json::from_json_str(include_str!("../🧫️fixtures/🔣️.json"), semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn database(snapshot:&En1996Snapshot)->SqliteDatabase{snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn roundtrip(snapshot:&En1996Snapshot)->En1996Snapshot{let bytes=export_sqlite_database(&database(snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();En1996Snapshot::from_sqlite_database(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn set_every_word(snapshot:&mut En1996Snapshot,value:f64){
    for wall in &mut snapshot.walls{wall.thickness_m=value;wall.height_m=value;wall.length_m=value;wall.slab_bearing_depth_m=value;wall.eccentricity_top_m=value;wall.eccentricity_bottom_m=value;wall.f_b_pa=value;wall.unit_length_m=value;wall.unit_width_m=value;wall.unit_height_m=value;wall.mortar_strength_pa=value;wall.bed_joint_thickness_m=value;wall.as_vertical_m2=value;wall.as_horizontal_m2=value;wall.f_yd_pa=value;wall.mu=value;wall.density_kg_m3=value;wall.phi_infinity=value;for opening in &mut wall.openings{opening.width_m=value;opening.height_m=value;opening.sill_height_m=value;}for case in &mut wall.load_cases{case.g_k_slab_n=value;case.q_k_imposed_pa=value;case.tributary_area_m2=value;case.slab_span_m=value;case.q_k_snow_pa=value;case.q_p_wind_pa=value;case.c_pe=value;case.h_k_earth_n=value;for load in &mut case.concentrated{load.force_n=value;load.bearing_area_m2=value;load.bearing_length_m=value;}}}
}

