#[test]
fn sqlite_snapshot_en1996_independent_sqlite_joins_and_domain_edits(){
    use std::{io::Write,process::{Command,Stdio}};
    let mut expected=fixture();let bytes=export_sqlite_database(&database(&expected),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
    let script="import{Database}from'bun:sqlite';import{Buffer}from'node:buffer';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const rows=db.query('SELECT w.label_de,c.design_situation,l.ordinal,l.force_n FROM en1996_wall w JOIN en1996_load_case c ON c.wall_id=w.id JOIN en1996_concentrated_load l ON l.load_case_id=c.id WHERE w.id=1 ORDER BY c.ordinal,l.ordinal').all();if(rows.length!==2||rows[0].force_n!==35000.25||rows[1].force_n!==-35000.25||rows[0].design_situation!=='arbitrary persisted situation')throw Error('ordered masonry relationships');const word=value=>{const b=Buffer.alloc(8);b.writeDoubleBE(value);return BigInt.asIntN(64,b.readBigUInt64BE())};db.run(\"UPDATE en1996_concentrated_load SET force_n=42.5,force_n_ieee754_bits=?,force_n_ieee754_class='finite' WHERE id=1\",[word(42.5)]);db.run(\"UPDATE en1996_wall SET label_de='Geändert 世界',support_sides=254 WHERE id=1\");db.run(\"UPDATE en1996_document SET design_situation='Transient',storeys=4294967294\");await Bun.write(Bun.stdout,db.serialize());db.close();";
    let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));
    expected.walls[0].load_cases[0].concentrated[0].force_n=42.5;expected.walls[0].label_de="Geändert 世界".into();expected.walls[0].support_sides=254;expected.design_situation=crate::document::DesignSituation::Transient;expected.storeys=4294967294;
    assert_eq!(En1996Snapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);
}

#[test]
fn sqlite_snapshot_en1996_refuses_malformed_choices_widths_booleans_ordinals_parents_and_words(){
    let database=database(&fixture());for(table,index,column,value)in[("en1996_document",0,4,SqliteValue::Integer(4294967296)),("en1996_document",0,1,SqliteValue::Text("unknown".into())),("en1996_document",0,2,SqliteValue::Text("unknown".into())),("en1996_document",0,3,SqliteValue::Text("unknown".into())),("en1996_wall",0,10,SqliteValue::Integer(256)),("en1996_wall",0,28,SqliteValue::Integer(-1)),("en1996_wall",0,6,SqliteValue::Text("unknown".into())),("en1996_wall",0,14,SqliteValue::Text("unknown".into())),("en1996_wall",0,15,SqliteValue::Text("unknown".into())),("en1996_wall",0,20,SqliteValue::Text("unknown".into())),("en1996_wall",0,21,SqliteValue::Text("unknown".into())),("en1996_wall",0,29,SqliteValue::Text("unknown".into())),("en1996_wall",0,24,SqliteValue::Integer(2)),("en1996_wall",0,1,SqliteValue::Integer(99)),("en1996_wall",1,2,SqliteValue::Integer(0)),("en1996_opening",0,1,SqliteValue::Integer(99)),("en1996_opening",0,2,SqliteValue::Integer(99)),("en1996_load_case",0,1,SqliteValue::Integer(99)),("en1996_load_case",1,2,SqliteValue::Integer(0)),("en1996_concentrated_load",0,1,SqliteValue::Integer(99)),("en1996_concentrated_load",0,2,SqliteValue::Integer(99)),("en1996_wall",0,35,SqliteValue::Text("nan".into()))]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows[index].values[column]=value;assert!(En1996Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}");}
    let mut invalid=database.clone();invalid.table_mut("en1996_document").unwrap().rows.clear();assert!(En1996Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());
}

#[test]
fn sqlite_snapshot_en1996_initial_and_nested_operations_support_cancellation_and_native_admission(){
    let mut snapshot=fixture();assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:1,..SqliteDatabaseLimits::default()})).is_err());assert!(En1996Snapshot::from_sqlite_database(&database(&snapshot),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:0,..SqliteDatabaseLimits::default()})).is_err());
    for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1024,..SqliteDatabaseLimits::default()})).unwrap_err().to_string().contains("native encoding exceeds file byte limit"));}
    let controls:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🎛️control.json")).unwrap();snapshot.walls[0].load_cases[0].concentrated=vec![snapshot.walls[0].load_cases[0].concentrated[0].clone();controls["entityCount"].as_u64().unwrap()as usize];let cancel_at=controls["cancelAt"].as_u64().unwrap()as usize;
    for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut reached=false;assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut|event|{if event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>=cancel_at{reached=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(reached);}
    let large=database(&snapshot);for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot]{let mut reached=false;let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.completed>=cancel_at{reached=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(if phase==SqliteSnapshotPhase::ProjectSnapshot{snapshot.to_sqlite_database(&mut control).is_err()}else{En1996Snapshot::from_sqlite_database(&large,&mut control).is_err()});assert!(reached);}
}

#[test]
fn sqlite_snapshot_en1996_large_owned_text_cancels_before_projection_reconstruction_and_encoding_copy(){let mut snapshot=fixture();snapshot.walls[0].label_de="x".repeat(131073);let database=database(&snapshot);for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot,SqliteSnapshotPhase::EncodeNative]{let mut reached=false;let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.total>=65536&&event.completed>=65536&&event.completed<event.total{reached=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());let rejected=match phase{SqliteSnapshotPhase::ProjectSnapshot=>snapshot.to_sqlite_database(&mut control).is_err(),SqliteSnapshotPhase::ReconstructSnapshot=>En1996Snapshot::from_sqlite_database(&database,&mut control).is_err(),_=>snapshot.encode_sqlite_snapshot_native(SnapshotEncoding::Text,&mut control).is_err()};assert!(rejected);assert!(reached);}}

